func (this *Cex) ParseWsTicker(ticker map[string]any, optionalArgs ...any) any {
	//
	//  public
	//    {
	//        "symbol1": "LRC",
	//        "symbol2": "USD",
	//        "price": "0.305",
	//        "open24": "0.301",
	//        "volume": "241421.641700"
	//    }
	//  private
	//    {
	//        "timestamp": "1663764969",
	//        "low": "18756.3",
	//        "high": "19200",
	//        "last": "19200",
	//        "volume": "0.94735907",
	//        "volume30d": "64.61299999",
	//        "bid": 19217.2,
	//        "ask": 19247.5,
	//        "priceChange": "44.3",
	//        "priceChangePercentage": "0.23",
	//        "pair": ["BTC", "USDT"]
	//    }
	var market map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = market
	var pair []any = ccxt.SafeListTypedDefault(ticker, "pair", []any{})
	var baseId *string = this.SafeString(ticker, "symbol1")
	if baseId == nil {
		baseId = this.SafeString(pair, 0)
	}
	var quoteId *string = this.SafeString(ticker, "symbol2")
	if quoteId == nil {
		quoteId = this.SafeString(pair, 1)
	}
	var base *string = this.SafeCurrencyCode(baseId)
	var quote *string = this.SafeCurrencyCode(quoteId)
	var symbol any = ccxt.Add(ccxt.Add(base, "/"), quote)
	var timestamp any = ccxt.DerefScalar(this.SafeInteger(ticker, "timestamp"))
	if !ccxt.IsEqual(timestamp, nil) {
		timestamp = ccxt.Multiply(timestamp, 1000)
	}
	return this.SafeTicker(map[string]any{
		"symbol":        symbol,
		"timestamp":     timestamp,
		"datetime":      this.Iso8601(timestamp),
		"high":          this.SafeString(ticker, "high"),
		"low":           this.SafeString(ticker, "low"),
		"bid":           this.SafeString(ticker, "bid"),
		"bidVolume":     nil,
		"ask":           this.SafeString(ticker, "ask"),
		"askVolume":     nil,
		"vwap":          nil,
		"open":          this.SafeString(ticker, "open24"),
		"close":         nil,
		"last":          this.SafeString2(ticker, "price", "last"),
		"previousClose": nil,
		"change":        this.SafeString(ticker, "priceChange"),
		"percentage":    this.SafeString(ticker, "priceChangePercentage"),
		"average":       nil,
		"baseVolume":    nil,
		"quoteVolume":   this.SafeString(ticker, "volume"),
		"info":          ticker,
	}, market)
}

